// Removes everything generated by installing, running or building the project:
// node_modules/ (including Vite's dependency cache), dist/, and the ZK artifacts
// that copy-zk-artifacts.mjs copies into public/. package-lock.json is kept.
import { rm } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const rootDir = path.dirname(path.dirname(fileURLToPath(import.meta.url)));

for (const dir of [
  "node_modules",
  "dist",
  "public/keys",
  "public/zkir",
  "public/compiler",
]) {
  await rm(path.join(rootDir, dir), { recursive: true, force: true });
  console.log(`Removed ${dir}/`);
}
